/**
 * Dynamic ard.json Route
 *
 * Serves the Agentic Resource Discovery manifest only when custom content is
 * set in settings. No content is generated by default.
 * See: https://agenticresourcediscovery.org/spec/
 */

import { NextResponse } from 'next/server';
import { ARD_JSON_SETTING_KEY, serializeArdManifest } from '@/lib/ard-manifest';
import { getSettingByKey } from '@/lib/repositories/settingsRepository';
import { tagResponseForPublish } from '@/lib/response-cache-tag';

export async function GET() {
  try {
    await tagResponseForPublish();

    const manifest = serializeArdManifest(await getSettingByKey(ARD_JSON_SETTING_KEY));

    if (manifest) {
      return new NextResponse(manifest, {
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          // Agents and validators fetch the manifest cross-origin.
          'Access-Control-Allow-Origin': '*',
          'Cache-Control': 'public, max-age=86400, s-maxage=86400',
        },
      });
    }

    return new NextResponse(null, { status: 404 });
  } catch (error) {
    console.error('[ard.json] Error:', error);
    return new NextResponse(null, { status: 404 });
  }
}
